const d = $input.first().json || {};
const taskId = (d.taskId || '').toString().trim();
const taskType = (d.taskType || '').toString().trim();
const title = (d.title || '').toString().trim();
const bodyText = (d.bodyText || '').toString();
const notionDataSourceId = (d.notionDataSourceId || '').toString().trim();
const lineMessagePrefix = (d.lineMessagePrefix || '').toString();

const missing = [];
if (!taskId) missing.push('taskId');
if (!taskType) missing.push('taskType');
if (!title) missing.push('title');
if (!bodyText) missing.push('bodyText');
if (!notionDataSourceId) missing.push('notionDataSourceId');
const validationError = missing.length > 0 ? ('必須項目が不足しています: ' + missing.join(', ')) : null;

function simpleHash(str) {
  let h = 0;
  for (let i = 0; i < str.length; i++) { h = (h * 31 + str.charCodeAt(i)) >>> 0; }
  return h.toString(36).toUpperCase();
}
const typePrefix = (taskType.replace(/[^a-zA-Z0-9]/g, '').slice(0, 3) || 'TSK').toUpperCase();
const approvalKeyword = validationError ? null : (typePrefix + '-' + simpleHash(taskId + '|' + Date.now()).slice(-4));

return [{
  json: {
    taskId, taskType, title, bodyText, notionDataSourceId, lineMessagePrefix,
    approvalKeyword, validationError, requestedAt: new Date().toISOString()
  }
}];

const validated = $('入力検証・承認キーワード生成').first().json;
const queryResp = $input.first().json;
let finalKeyword = validated.approvalKeyword;
let collisionNote = null;

if (queryResp && queryResp.error) {
  collisionNote = '重複確認クエリに失敗しました（detail=' + JSON.stringify(queryResp.error) + '）。衝突確認をスキップしてこのまま採番したキーワードを使用します。';
} else {
  const count = (queryResp.results || []).length;
  if (count > 0) {
    finalKeyword = finalKeyword + '-' + (count + 1);
    collisionNote = '同一キーワードの承認待ちタスクが' + count + '件存在したため、末尾に連番を付与しました（簡易的な衝突回避）。';
  }
}

return [{
  json: {
    ...validated,
    approvalKeyword: finalKeyword,
    collisionNote
  }
}];

const d = $input.first().json;

function chunk(str, size) {
  const out = [];
  for (let i = 0; i < str.length; i += size) out.push(str.slice(i, i + size));
  return out.length ? out : [''];
}
function textBlock(content) {
  return { object: 'block', type: 'paragraph', paragraph: { rich_text: [ { type: 'text', text: { content } } ] } };
}

const children = [];
children.push(textBlock('タスク種別: ' + d.taskType));
children.push(textBlock('承認方法: このページの内容を確認し、問題なければLINEに「' + d.approvalKeyword + '」とだけ返信してください。'));
children.push(textBlock('--- 内容 ---'));
for (const line of (d.bodyText || '').split('\n')) {
  for (const part of chunk(line, 1900)) {
    children.push(textBlock(part));
  }
}
const limited = children.slice(0, 97);

const properties = {
  'Name': { title: [ { text: { content: d.title } } ] },
  'タスクID': { rich_text: [ { text: { content: d.taskId } } ] },
  'タスク種別': { rich_text: [ { text: { content: d.taskType } } ] },
  'ステータス': { select: { name: '承認待ち' } },
  '承認キーワード': { rich_text: [ { text: { content: d.approvalKeyword } } ] },
  '作成日時': { date: { start: d.requestedAt } }
};

return [{
  json: {
    ...d,
    notionPageRequestBody: {
      parent: { type: 'data_source_id', data_source_id: d.notionDataSourceId },
      properties,
      children: limited
    }
  }
}];

const d = $input.first().json;
const validated = $('衝突解消・最終キーワード確定').first().json;
return [{ json: { success: false, error: 'Notion承認待ちタスクページの作成に失敗しました。', detail: d.error ? JSON.stringify(d.error) : JSON.stringify(d), taskId: validated.taskId } }];

const created = $input.first().json;
const d = $('衝突解消・最終キーワード確定').first().json;
const pageId = created.id;
const reviewUrl = 'https://www.notion.so/' + (pageId || '').replace(/-/g, '');
const prefix = d.lineMessagePrefix ? (d.lineMessagePrefix + '\n') : '';
const text = prefix + d.title + '\n確認: ' + reviewUrl + '\n\n内容に問題なければ、このLINEに「' + d.approvalKeyword + '」とだけ返信してください。それ以外の内容は承認とみなしません。';
return [{
  json: {
    lineRequestBody: { messages: [ { type: 'text', text } ] },
    reviewPageId: pageId,
    reviewUrl,
    approvalKeyword: d.approvalKeyword,
    taskId: d.taskId,
    taskType: d.taskType
  }
}];

const lineResp = $input.first().json;
const ctx = $('LINEメッセージ本文生成').first().json;
const lineSendSuccess = !(lineResp && lineResp.error);
return [{
  json: {
    success: true,
    reviewPageId: ctx.reviewPageId,
    reviewUrl: ctx.reviewUrl,
    approvalKeyword: ctx.approvalKeyword,
    taskId: ctx.taskId,
    taskType: ctx.taskType,
    lineSendSuccess,
    lineSendDetail: lineSendSuccess ? null : JSON.stringify(lineResp.error)
  }
}];
